import{_ as d,o,c as e,a6 as r}from"./chunks/framework.BrkgobfX.js";const g=JSON.parse('{"title":"SETTINGS 与优先级","description":"六个 SETTINGS 参数、ACK 机制，以及优先级树的废弃与 RFC 9218 扩展优先级。","frontmatter":{"title":"SETTINGS 与优先级","description":"六个 SETTINGS 参数、ACK 机制，以及优先级树的废弃与 RFC 9218 扩展优先级。","source":"https://daiw.org/manual/http2-3/h2-settings-priority"},"headers":[],"relativePath":"manual/computer-programming/http2-3/h2-settings-priority.md","filePath":"manual/computer-programming/http2-3/h2-settings-priority.md"}'),a={name:"manual/computer-programming/http2-3/h2-settings-priority.md"};function n(i,t,s,c,l,h){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="settings-与优先级" tabindex="-1">SETTINGS 与优先级 <a class="header-anchor" href="#settings-与优先级" aria-label="Permalink to &quot;SETTINGS 与优先级&quot;">​</a></h1><p>六个 SETTINGS 参数、ACK 机制，以及优先级树的废弃与 RFC 9218 扩展优先级。</p><h2 id="settings-帧" tabindex="-1">SETTINGS 帧 <a class="header-anchor" href="#settings-帧" aria-label="Permalink to &quot;SETTINGS 帧&quot;">​</a></h2><p>连接级参数协商，流 ID <strong>MUST</strong> 为 0。</p><p>机制要点：</p><ul><li><strong>不是握手，是单向声明</strong>：每一端各自声明「<strong>我这边</strong>的接收能力」。双方的值互相独立，无需一致。</li><li>载荷是若干 6 字节条目：2 字节标识符 + 4 字节值。载荷长度不是 6 的倍数 → <code>FRAME_SIZE_ERROR</code>。</li><li>接收方 <strong>MUST</strong> 立即（在处理后续帧之前）应用这些值，并回一个置 <code>ACK</code> 标志（<code>0x01</code>）的空 <code>SETTINGS</code>。</li><li>带 <code>ACK</code> 的帧载荷长度必须为 0，否则 <code>FRAME_SIZE_ERROR</code>。</li><li>长时间收不到 ACK <strong>MAY</strong> 以 <code>SETTINGS_TIMEOUT</code> 关闭连接。</li><li>未知标识符 <strong>MUST</strong> 被忽略（扩展点）。</li></ul><h2 id="六个标准参数" tabindex="-1">六个标准参数 <a class="header-anchor" href="#六个标准参数" aria-label="Permalink to &quot;六个标准参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>名称</th><th>默认值</th><th>语义</th></tr></thead><tbody><tr><td><code>0x01</code></td><td><code>HEADER_TABLE_SIZE</code></td><td>4096</td><td>对端 <a href="/Front2Full/manual/computer-programming/http2-3/hpack">HPACK 动态表</a>上限（字节）</td></tr><tr><td><code>0x02</code></td><td><code>ENABLE_PUSH</code></td><td>1</td><td>是否允许<a href="/Front2Full/manual/computer-programming/http2-3/h2-server-push">服务端推送</a>；只能取 0/1，其他值 → <code>PROTOCOL_ERROR</code></td></tr><tr><td><code>0x03</code></td><td><code>MAX_CONCURRENT_STREAMS</code></td><td>无限</td><td>对端可同时打开的流数</td></tr><tr><td><code>0x04</code></td><td><code>INITIAL_WINDOW_SIZE</code></td><td>65535</td><td>流级<a href="/Front2Full/manual/computer-programming/http2-3/h2-flow-control">流量控制</a>初始窗口；&gt; 2^31−1 → <code>FLOW_CONTROL_ERROR</code></td></tr><tr><td><code>0x05</code></td><td><code>MAX_FRAME_SIZE</code></td><td>16384</td><td>可接收的最大帧载荷；<strong>合法范围 16384 – 16777215</strong>，越界 → <code>PROTOCOL_ERROR</code></td></tr><tr><td><code>0x06</code></td><td><code>MAX_HEADER_LIST_SIZE</code></td><td>无限</td><td>可接收的字段列表未压缩大小上限（含每字段 32 字节开销）；仅为<strong>建议</strong></td></tr></tbody></table><p>生产调优的三个重点：</p><ol><li><code>INITIAL_WINDOW_SIZE</code> —— 默认 65535 在高 BDP 链路上严重限速，通常调到 MB 级。</li><li><code>MAX_CONCURRENT_STREAMS</code> —— 默认无限意味着无防护，<strong>必须</strong>设有限值（常见 100–128），否则易受流洪泛。</li><li><code>MAX_HEADER_LIST_SIZE</code> —— 默认无限，是 HPACK 炸弹的防线，应显式设置。</li></ol><h2 id="优先级-一段被推翻的设计" tabindex="-1">优先级：一段被推翻的设计 <a class="header-anchor" href="#优先级-一段被推翻的设计" aria-label="Permalink to &quot;优先级：一段被推翻的设计&quot;">​</a></h2><h3 id="rfc-7540-的优先级树-已废弃" tabindex="-1">RFC 7540 的优先级树（已废弃） <a class="header-anchor" href="#rfc-7540-的优先级树-已废弃" aria-label="Permalink to &quot;RFC 7540 的优先级树（已废弃）&quot;">​</a></h3><p>原设计中，<code>PRIORITY</code> 帧与 <code>HEADERS</code> 的优先级字段可构建一棵<strong>依赖树</strong>：</p><ul><li>每个流可声明<strong>依赖</strong>另一个流（<code>Stream Dependency</code>）。</li><li>同层兄弟按<strong>权重</strong>（1–256）按比例分配带宽。</li><li>支持<strong>独占依赖</strong>（<code>E</code> 标志），把原有兄弟全部改挂到自己名下。</li></ul><p><strong>RFC 9113 已将其全部废弃</strong>（deprecated）。废弃原因，逐条：</p><table tabindex="0"><thead><tr><th>问题</th><th>说明</th></tr></thead><tbody><tr><td>过度复杂</td><td>服务端要维护每连接一棵可变树，含已关闭流的「幽灵节点」</td></tr><tr><td>实现分歧大</td><td>各服务端调度策略互不兼容，客户端无法预期效果</td></tr><tr><td>浏览器各行其是</td><td>Chrome 用线性链、Firefox 用分组树，服务端难以同时优化</td></tr><tr><td>收益不明</td><td>实测多数场景与简单的 FIFO/轮转差别不大</td></tr><tr><td>攻击面</td><td>恶意构造的深树消耗服务端内存与 CPU</td></tr></tbody></table><p>现状：端点<strong>仍 MUST 能解析</strong>这些字段（向后兼容，收到即忽略），但 <strong>SHOULD NOT</strong> 再生成。多数现代服务端直接无视优先级树。</p><h3 id="rfc-9218-扩展优先级-现行方案" tabindex="-1">RFC 9218 扩展优先级（现行方案） <a class="header-anchor" href="#rfc-9218-扩展优先级-现行方案" aria-label="Permalink to &quot;RFC 9218 扩展优先级（现行方案）&quot;">​</a></h3><p>替代方案把优先级从「二进制帧里的树」改成了<strong>普通的 HTTP 字段</strong>，且 h2 与 h3 <strong>通用</strong>：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">priority</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> u=1, i</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>两个参数（<a href="/Front2Full/manual/computer-programming/http11/field-syntax">结构化字段</a>语法）：</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>取值</th><th>语义</th></tr></thead><tbody><tr><td><code>u</code></td><td>整数</td><td><strong>0–7</strong>，默认 <strong>3</strong></td><td>紧急度，<strong>数值越小优先级越高</strong></td></tr><tr><td><code>i</code></td><td>布尔</td><td>默认 false</td><td>incremental：为真表示可<strong>渐进式</strong>呈现（如渐进 JPEG、HTML 流式渲染）</td></tr></tbody></table><p>用法：</p><ul><li>客户端在请求的 <code>priority</code> 字段中声明。</li><li>服务端可在响应中用 <code>priority</code> 字段<strong>覆盖</strong>（服务端更清楚资源性质）。</li><li>也可用 <code>PRIORITY_UPDATE</code> 帧（h2 类型 <code>0x10</code>，h3 类型 <code>0xF0700</code>/<code>0xF0701</code>）在请求发出后<strong>动态改</strong>。</li><li><code>i=?1</code> 的同优先级流应<strong>轮转</strong>调度（让多个可渐进资源同时推进）；<code>i=?0</code> 的应<strong>顺序</strong>完成（一个一个来，早点可用）。</li></ul><p>设计上的进步：无状态、可读、可被中间件理解、h2/h3 统一——而不是一棵需要双方精确同步的树。</p><p>下一篇：<a href="/Front2Full/manual/computer-programming/http2-3/h2-connection">连接管理与错误码</a>。</p>',26)])])}const u=d(a,[["render",n]]);export{g as __pageData,u as default};
